script:
(function () {
  'use strict';

  var btnLeft = document.getElementById('btnLeft');
  var btnRight = document.getElementById('btnRight');
  var btnBoth = document.getElementById('btnBoth');
  var btnAlternate = document.getElementById('btnAlternate');
  var btnStop = document.getElementById('btnStop');
  var volumeSlider = document.getElementById('volumeSlider');
  var volumeValue = document.getElementById('volumeValue');
  var outputSelectRow = document.getElementById('outputSelectRow');
  var outputSelect = document.getElementById('outputSelect');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var toolError = document.getElementById('toolError');
  var statExpected = document.getElementById('statExpected');
  var statSignal = document.getElementById('statSignal');
  var statLeft = document.getElementById('statLeft');
  var statRight = document.getElementById('statRight');
  var statPolarity = document.getElementById('statPolarity');
  var statPlayTime = document.getElementById('statPlayTime');
  var tonePreset = document.getElementById('tonePreset');
  var freqSlider = document.getElementById('freqSlider');
  var freqValue = document.getElementById('freqValue');
  var polaritySelect = document.getElementById('polaritySelect');
  var durationSelect = document.getElementById('durationSelect');

  var MAX_GAIN = 0.4; // conservative ceiling -- see this site's safety notes for playback tools
  var RAMP_SECONDS = 0.02; // ramp every tone in/out to avoid audible clicks
  var TONE_FREQ = 440; // A4 -- a mid frequency every speaker can reproduce cleanly
  var CENTER_LEVEL = Math.SQRT1_2; // equal-power centre, same loudness as the old centred StereoPanner
  var ALTERNATE_MS = 1500;

  var Ctor = window.AudioContext || window.webkitAudioContext;
  var audioCtx = null;
  var master = null, gainL = null, gainR = null, analyserL = null, analyserR = null;
  var oscillator = null, env = null;
  var activeBtn = null;
  var mode = null; // 'left' | 'right' | 'both' | 'alternate'
  var side = 'both'; // side currently routed
  var alternateInterval = null;
  var stopTimer = null;
  var meterTimer = null;
  var bufL = null, bufR = null;

  function showError(msg) {
    if (!toolError) return;
    toolError.textContent = msg;
    toolError.classList.add('show');
  }
  function clearError() {
    if (!toolError) return;
    toolError.textContent = '';
    toolError.classList.remove('show');
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span>' + it.html + '</span></div>';
    }).join('');
  }

  function currentGainTarget() {
    return (parseFloat(volumeSlider.value) / 100) * MAX_GAIN;
  }

  // Preset wins unless it's set to "custom", in which case the slider is used.
  function currentFreq() {
    var p = tonePreset.value;
    return p === 'custom' ? (parseFloat(freqSlider.value) || TONE_FREQ) : parseFloat(p);
  }

  function formatFreq(f) {
    return f >= 1000 ? (f / 1000).toFixed(f % 1000 ? 2 : 0) + ' kHz' : f + ' Hz';
  }

  function playTimeText() {
    var s = parseFloat(durationSelect.value);
    return s ? s + ' s' : 'Continuous';
  }

  // oscillator -> env -> gainL -> merger[0]
  //                   -> gainR -> merger[1] -> master -> destination
  // master -> splitter -> analyserL / analyserR (left/right level readouts).
  // Two independent gains into a ChannelMerger give hard L/R routing and let
  // the right gain go negative for the out-of-phase centre check.
  function buildGraph() {
    master = audioCtx.createGain();
    master.gain.value = currentGainTarget();
    gainL = audioCtx.createGain();
    gainR = audioCtx.createGain();
    gainL.gain.value = 0;
    gainR.gain.value = 0;
    var merger = audioCtx.createChannelMerger(2);
    gainL.connect(merger, 0, 0);
    gainR.connect(merger, 0, 1);
    merger.connect(master);
    master.connect(audioCtx.destination);
    var splitter = audioCtx.createChannelSplitter(2);
    analyserL = audioCtx.createAnalyser();
    analyserR = audioCtx.createAnalyser();
    analyserL.fftSize = analyserR.fftSize = 2048;
    master.connect(splitter);
    splitter.connect(analyserL, 0);
    splitter.connect(analyserR, 1);
  }

  function ensureContext() {
    if (!Ctor) {
      showError('Your browser doesn’t support Web Audio, so the channel test can’t play here.');
      return Promise.reject(new Error('no-webaudio'));
    }
    if (!audioCtx) {
      try {
        audioCtx = new Ctor();
      } catch (e) {
        showError('The browser refused to start audio output: ' + (e && e.message ? e.message : e));
        return Promise.reject(e);
      }
      buildGraph();
    }
    // AudioContext starts suspended under autoplay policy -- this always
    // runs from inside a click handler (a real user gesture), so resume()
    // is allowed to succeed immediately.
    return audioCtx.state === 'suspended' ? audioCtx.resume().then(function () { return audioCtx; }) : Promise.resolve(audioCtx);
  }

  function withContext(fn) {
    ensureContext().then(function () {
      clearError();
      fn();
    }).catch(function (e) {
      if (e && e.message === 'no-webaudio') return;
      showError('Audio could not start: ' + (e && e.message ? e.message : e));
    });
  }

  function routeTo(newSide, immediate) {
    side = newSide;
    if (!audioCtx || !gainL) return;
    var l = 0, r = 0;
    if (newSide === 'left') l = 1;
    else if (newSide === 'right') r = 1;
    else {
      l = CENTER_LEVEL;
      r = polaritySelect.value === 'out' ? -CENTER_LEVEL : CENTER_LEVEL;
    }
    var now = audioCtx.currentTime;
    [[gainL, l], [gainR, r]].forEach(function (pair) {
      pair[0].gain.cancelScheduledValues(now);
      if (immediate) pair[0].gain.setValueAtTime(pair[1], now);
      else pair[0].gain.setTargetAtTime(pair[1], now, 0.01);
    });
    updateOutputs();
  }

  // "Where you should hear it" + "If you hear something else" + polarity.
  function expectation() {
    if (side === 'left') return { where: 'Left only', ifWrong: 'If it comes from the right, your channels are swapped; if it comes from both sides, output may be set to mono.' };
    if (side === 'right') return { where: 'Right only', ifWrong: 'If it comes from the left, your channels are swapped; if it comes from both sides, output may be set to mono.' };
    if (polaritySelect.value === 'out') return { where: 'Wide, hollow', ifWrong: 'Out of phase should sound diffuse and thin. If it sounds more solid than in phase, one speaker is wired backwards.' };
    return { where: 'Centre', ifWrong: 'If the sound pulls to one side, check your balance setting, your seat position and each speaker’s volume.' };
  }

  function updateOutputs() {
    statPlayTime.textContent = playTimeText();
    statPolarity.textContent = polaritySelect.value === 'out' ? 'Out of phase' : 'In phase';
    if (!mode) {
      statExpected.textContent = '—';
      statSignal.textContent = '—';
      return;
    }
    statExpected.textContent = (mode === 'alternate' ? 'Alt · ' : '') + expectation().where;
    statSignal.textContent = formatFreq(currentFreq()) + ' sine';
  }

  function sideDiag() {
    var label = side === 'left' ? 'left' : (side === 'right' ? 'right' : (polaritySelect.value === 'out' ? 'both, out of phase' : 'both (centered)'));
    return '<strong>Playing ' + label + '.</strong> ' + expectation().ifWrong;
  }

  function clearTimers() {
    if (alternateInterval) { clearInterval(alternateInterval); alternateInterval = null; }
    if (stopTimer) { clearTimeout(stopTimer); stopTimer = null; }
  }

  function releaseSource() {
    if (!oscillator || !audioCtx) { oscillator = null; env = null; return; }
    var o = oscillator, e = env;
    oscillator = null;
    env = null;
    var now = audioCtx.currentTime;
    e.gain.cancelScheduledValues(now);
    e.gain.setValueAtTime(e.gain.value, now);
    e.gain.linearRampToValueAtTime(0, now + RAMP_SECONDS);
    setTimeout(function () {
      try { o.stop(); } catch (err) {}
      try { o.disconnect(); e.disconnect(); } catch (err) {}
    }, RAMP_SECONDS * 1000 + 30);
  }

  function stopTone() {
    clearTimers();
    releaseSource();
    mode = null;
    if (activeBtn) { activeBtn.classList.remove('active'); activeBtn = null; }
    btnStop.disabled = true;
    stopMeters();
    updateOutputs();
  }

  function startOscillator() {
    env = audioCtx.createGain();
    env.gain.value = 0;
    env.connect(gainL);
    env.connect(gainR);
    oscillator = audioCtx.createOscillator();
    oscillator.type = 'sine';
    oscillator.frequency.value = currentFreq();
    oscillator.connect(env);
    var now = audioCtx.currentTime;
    oscillator.start(now);
    env.gain.setValueAtTime(0, now);
    env.gain.linearRampToValueAtTime(1, now + RAMP_SECONDS);
  }

  function scheduleAutoStop() {
    var secs = parseFloat(durationSelect.value);
    if (!secs) return;
    stopTimer = setTimeout(function () {
      stopTone();
      setDiagnostic([{ sev: '', html: 'Finished (' + secs + ' s play time).' }]);
    }, secs * 1000);
  }

  function begin(newMode, btn, initialSide) {
    clearTimers();
    if (activeBtn) { activeBtn.classList.remove('active'); activeBtn = null; }
    mode = newMode;
    var fresh = !oscillator;
    routeTo(initialSide, fresh);
    if (fresh) startOscillator();
    if (btn) { activeBtn = btn; btn.classList.add('active'); }
    btnStop.disabled = false;
    updateOutputs();
    startMeters();
    scheduleAutoStop();
  }

  function playSide(newSide, btn) {
    withContext(function () {
      begin(newSide, btn, newSide);
      setDiagnostic([{ sev: 'ok', html: sideDiag() }]);
    });
  }

  function playAlternating() {
    withContext(function () {
      begin('alternate', btnAlternate, 'left');
      setDiagnostic([{ sev: 'ok', html: '<strong>Alternating left / right.</strong> The side should switch roughly every second and a half.' }]);
      alternateInterval = setInterval(function () {
        if (!oscillator) return;
        routeTo(side === 'left' ? 'right' : 'left', false);
        setDiagnostic([{ sev: 'ok', html: '<strong>Now playing: ' + side + '.</strong> ' + expectation().ifWrong }]);
      }, ALTERNATE_MS);
    });
  }

  // Left / right channel level, as a percentage of the louder channel --
  // read from the actual output (post-routing), so 100% / 0% means the
  // signal really is on one side only.
  function rms(buf) {
    var sum = 0;
    for (var i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
    return Math.sqrt(sum / buf.length);
  }
  function readMeters() {
    if (!analyserL || !mode) return;
    if (!bufL) { bufL = new Float32Array(analyserL.fftSize); bufR = new Float32Array(analyserR.fftSize); }
    analyserL.getFloatTimeDomainData(bufL);
    analyserR.getFloatTimeDomainData(bufR);
    var rL = rms(bufL), rR = rms(bufR), top = Math.max(rL, rR);
    statLeft.textContent = top > 1e-5 ? Math.round((rL / top) * 100) + '%' : '0%';
    statRight.textContent = top > 1e-5 ? Math.round((rR / top) * 100) + '%' : '0%';
  }
  function startMeters() {
    if (!meterTimer) meterTimer = setInterval(readMeters, 150);
  }
  function stopMeters() {
    if (meterTimer) { clearInterval(meterTimer); meterTimer = null; }
    statLeft.textContent = '—';
    statRight.textContent = '—';
  }

  function applyFrequency() {
    var f = currentFreq();
    if (tonePreset.value !== 'custom') freqSlider.value = f;
    freqValue.textContent = (parseFloat(freqSlider.value) || TONE_FREQ) + ' Hz';
    if (oscillator && audioCtx) oscillator.frequency.setTargetAtTime(f, audioCtx.currentTime, 0.015);
    updateOutputs();
  }

  btnLeft.addEventListener('click', function () { playSide('left', btnLeft); });
  btnRight.addEventListener('click', function () { playSide('right', btnRight); });
  btnBoth.addEventListener('click', function () { playSide('both', btnBoth); });
  btnAlternate.addEventListener('click', playAlternating);
  btnStop.addEventListener('click', function () {
    stopTone();
    setDiagnostic([{ sev: '', html: 'Stopped.' }]);
  });

  tonePreset.addEventListener('change', applyFrequency);
  freqSlider.addEventListener('input', function () {
    tonePreset.value = 'custom';
    applyFrequency();
  });
  polaritySelect.addEventListener('change', function () {
    updateOutputs();
    if (oscillator && audioCtx) {
      routeTo(side, false);
      if (side === 'both' && mode !== 'alternate') setDiagnostic([{ sev: 'ok', html: sideDiag() }]);
    }
  });
  durationSelect.addEventListener('change', function () {
    updateOutputs();
    if (!mode) return;
    if (stopTimer) { clearTimeout(stopTimer); stopTimer = null; }
    scheduleAutoStop();
  });

  volumeSlider.addEventListener('input', function () {
    volumeValue.textContent = volumeSlider.value + '%';
    if (master && audioCtx) {
      var now = audioCtx.currentTime;
      master.gain.cancelScheduledValues(now);
      master.gain.setValueAtTime(master.gain.value, now);
      master.gain.linearRampToValueAtTime(currentGainTarget(), now + 0.05);
    }
  });

  // setSinkId on AudioContext is a newer, Chromium-leaning API -- feature-
  // detect rather than assume, and hide the picker entirely when it isn't
  // available instead of shipping a dead dropdown. Identical to
  // speaker-test-online.json's own initOutputDevices().
  function initOutputDevices() {
    var supportsSinkId = Ctor && 'setSinkId' in Ctor.prototype;
    if (!supportsSinkId || !navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return;

    navigator.mediaDevices.enumerateDevices().then(function (devices) {
      var outputs = devices.filter(function (d) { return d.kind === 'audiooutput'; });
      if (!outputs.length) return;
      outputSelectRow.style.display = 'flex';
      outputSelect.innerHTML = outputs.map(function (d, i) {
        return '<option value="' + d.deviceId + '">' + (d.label || ('Output ' + (i + 1))) + '</option>';
      }).join('');
      outputSelect.addEventListener('change', function () {
        ensureContext().then(function () {
          audioCtx.setSinkId(outputSelect.value).catch(function () {
            setDiagnostic([{ sev: 'warn', html: 'Could not switch output device — your browser rejected the request.' }]);
          });
        }).catch(function () {});
      });
    }).catch(function () {});
  }

  window.addEventListener('pagehide', function () {
    stopTone();
    if (audioCtx) audioCtx.close().catch(function () {});
    audioCtx = null;
    master = gainL = gainR = analyserL = analyserR = null;
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') {
      stopTone();
      if (audioCtx && audioCtx.state === 'running') audioCtx.suspend().catch(function () {});
    }
  });

  initOutputDevices();
  applyFrequency();

  if (!Ctor) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support Web Audio.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    [btnLeft, btnRight, btnBoth, btnAlternate].forEach(function (b) { b.disabled = true; });
  }
})();
